original = {
    'url': 'https://jmcomicqa.cc',
    'name': '寿横',
    'tag': 0,
    'usedIndexes': []
};
let cachedPageHtml = null;
try {
    $$$ = JSON.parse(source.getVariable());
    if ($$$ == null) {
        error;
    } else {
        if (!$$$.hasOwnProperty('usedIndexes')) $$$.usedIndexes = [];
    };
} catch (e) {
    $$$ = original;
    put($$$);
}

function put(data) {
    return source.setVariable(JSON.stringify(data, null, '\t'));
}

function n(e) {
    n = '\n';
    for (m = 1; m < e; m++) {
        n = n + '\n';
    }
    return n;
}

function log(e) {
    if (e == undefined) {
        return;
    }
    java.longToast(e);
}

const regexList = [
    /china"><span>(.*?)<\/span>/,
    /first_line"><span>(.*?)<\/span>/,
    /second_line"><span>(.*?)<\/span>/
];

function getRandomUnusedIndex() {
    if ($$$.usedIndexes.length === regexList.length) {
        $$$.usedIndexes = [];
    }
    let randomIndex;
    do {
        randomIndex = Math.floor(Math.random() * regexList.length);
    } while ($$$.usedIndexes.includes(randomIndex));
    $$$.usedIndexes.push(randomIndex);
    put($$$);
    return randomIndex;
}

function login() {
    result = JSON.parse(source.getLoginInfo());
    var username = result['账号'];
    $$$.name = username;
    var password = result['密码'];
    var options = {
        body: `username=${username}&password=${password}&submit_login=1`,
        method: 'POST'
    }
    if (!cachedPageHtml) {
        cachedPageHtml = java.ajax(`https://jmcomicqa.cc`);
    }
    const randomIndex = getRandomUnusedIndex();
    const currentRegex = regexList[randomIndex];
    var url = cachedPageHtml.match(currentRegex)[1];
    $$$.url = url;
    put($$$);
    java.ajax(`${url}/login,${JSON.stringify(options)}`);
    return put($$$);
}

P = ['时间', '阅读', '收藏'];

function typeP(e) {
    if (e == undefined) {
        e = 0;
    }
    return P[e];
}

function tag(e) {
    if (typeof tag === 'undefined') {
        tag = $$$.tag;
    }
    if (e == $$$.tag) {
        return log('【标签切换提示】' + n(2) + '已经选择此标签，无需更换');
    }
    log('【标签切换提示】' + n(2) + '已经切换到[' + typeP(e) + ']');
    $$$.tag = e;
    return put($$$);
}

function url() {
    if (!cachedPageHtml) {
        cachedPageHtml = java.ajax(`https://jmcomicqa.cc`);
    }
    const randomIndex = getRandomUnusedIndex();
    const currentRegex = regexList[randomIndex];
    var url = cachedPageHtml.match(currentRegex)[1];
    if (url == $$$.url) {
        return log('【站点提示】' + n(2) + '站点无需更换');
    }
    log('站点变更:' + url);
    $$$.url = url;
    return put($$$);
}

